/****************************************************************************
 * apps/examples/elderly/ui_manager.c
 *
 * Page manager: handles page creation, switching, and lifecycle.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "ui_manager.h"
#include "ui_index.h"
#include "ui_health_detail.h"
#include "ui_settings.h"
#include "ui_wifi.h"
#include "ui_sos.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *g_pages[PAGE_COUNT];
static lv_obj_t *g_layer;     /* Top-level layer for overlays */
static page_id_t g_current = PAGE_INDEX;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void swipe_event_cb(lv_event_t *e)
{
  lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
  app_context_t *ctx = app_get_context();

  /* Don't allow swipe navigation when SOS is active */

  if (ctx->alarm.active)
    {
      return;
    }

  if (dir == LV_DIR_LEFT)
    {
      if (g_current < PAGE_COUNT - 1)
        {
          ui_manager_switch_page(g_current + 1);
        }
    }
  else if (dir == LV_DIR_RIGHT)
    {
      if (g_current > PAGE_INDEX)
        {
          ui_manager_switch_page(g_current - 1);
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void ui_manager_init(void)
{
  lv_obj_t *scr = lv_screen_active();

  /* Set black background */

  lv_obj_set_style_bg_color(scr, COLOR_BG, 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
  lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

  /* Create the content layer */

  g_layer = lv_obj_create(scr);
  lv_obj_set_size(g_layer, SCREEN_WIDTH, SCREEN_HEIGHT);
  lv_obj_center(g_layer);
  lv_obj_set_style_bg_opa(g_layer, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(g_layer, 0, 0);
  lv_obj_set_style_pad_all(g_layer, 0, 0);
  lv_obj_remove_flag(g_layer, LV_OBJ_FLAG_SCROLLABLE);

  /* Create all pages */

  g_pages[PAGE_INDEX] = ui_index_create(g_layer);
  g_pages[PAGE_HEALTH_DETAIL] = ui_health_detail_create(g_layer);
  g_pages[PAGE_SETTINGS] = ui_settings_create(g_layer);
  g_pages[PAGE_WIFI] = ui_wifi_create(g_layer);
  g_pages[PAGE_SOS] = ui_sos_create(g_layer);

  /* Hide all except the first page */

  for (int i = 0; i < PAGE_COUNT; i++)
    {
      if (i != PAGE_INDEX)
        {
          lv_obj_add_flag(g_pages[i], LV_OBJ_FLAG_HIDDEN);
        }
    }

  g_current = PAGE_INDEX;

  /* Add swipe gesture handler on the active screen */

  lv_obj_add_event_cb(scr, swipe_event_cb, LV_EVENT_GESTURE, NULL);
}

void ui_manager_switch_page(page_id_t page)
{
  if (page >= PAGE_COUNT || page == g_current)
    {
      return;
    }

  /* Hide current page */

  lv_obj_add_flag(g_pages[g_current], LV_OBJ_FLAG_HIDDEN);

  /* Show target page */

  lv_obj_remove_flag(g_pages[page], LV_OBJ_FLAG_HIDDEN);

  g_current = page;

  /* Sync settings page controls when entering settings */

  if (page == PAGE_SETTINGS)
    {
      ui_settings_sync_controls();
    }

  /* Update health detail when entering */

  if (page == PAGE_HEALTH_DETAIL)
    {
      ui_health_detail_update();
    }

  /* Refresh WiFi status when entering WiFi page */

  if (page == PAGE_WIFI)
    {
      ui_wifi_refresh();
    }
}

lv_obj_t *ui_manager_get_page(page_id_t page)
{
  if (page < PAGE_COUNT)
    {
      return g_pages[page];
    }

  return NULL;
}

void ui_manager_refresh(void)
{
  switch (g_current)
    {
      case PAGE_INDEX:
        ui_index_update_vitals();
        ui_index_update_steps();
        ui_index_update_health_status();
        break;

      case PAGE_HEALTH_DETAIL:
        ui_health_detail_update();
        break;

      default:
        break;
    }
}

lv_obj_t *ui_manager_get_layer(void)
{
  return g_layer;
}

/****************************************************************************
 * apps/examples/elderly/ui_manager.h
 *
 * Page manager: handles page creation, switching, and lifecycle.
 ****************************************************************************/

#ifndef __UI_MANAGER_H
#define __UI_MANAGER_H

#include "ui_common.h"

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/**
 * Initialize the UI manager and create all pages.
 * Call after LVGL is initialized.
 */

void ui_manager_init(void);

/**
 * Switch to a specific page with optional animation.
 */

void ui_manager_switch_page(page_id_t page);

/**
 * Get the LVGL screen object for a specific page.
 */

lv_obj_t *ui_manager_get_page(page_id_t page);

/**
 * Refresh the current page data (called by data collector).
 */

void ui_manager_refresh(void);

/**
 * Get the page container object (for overlay elements like SOS popup).
 */

lv_obj_t *ui_manager_get_layer(void);

#endif /* __UI_MANAGER_H */

/****************************************************************************
 * apps/examples/elderly/ui_common.h
 *
 * Common definitions for the Elderly Health Care LVGL application.
 * Colors, screen dimensions, shared data structures, and page IDs.
 ****************************************************************************/

#ifndef __UI_COMMON_H
#define __UI_COMMON_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <nuttx/config.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Screen dimensions (circular AMOLED display) */

#define SCREEN_WIDTH        CONFIG_EXAMPLES_ELDERLY_BES_SCREEN_WIDTH
#define SCREEN_HEIGHT       CONFIG_EXAMPLES_ELDERLY_BES_SCREEN_HEIGHT
#define SCREEN_RADIUS       (SCREEN_WIDTH < SCREEN_HEIGHT ? SCREEN_WIDTH / 2 : SCREEN_HEIGHT / 2)

/* Safe margin for circular display: content must stay within inscribed square.
 * For a 454px circle, inscribed square side = 454 / sqrt(2) ≈ 321
 * Safe margin = (454 - 321) / 2 ≈ 66px. Use 50px as practical compromise.
 */

#define SAFE_MARGIN         50
#define CONTENT_WIDTH       (SCREEN_WIDTH - 2 * SAFE_MARGIN)

/* Color palette (dark theme for OLED) */

#define COLOR_BG            lv_color_hex(0x000000)
#define COLOR_CARD_BG       lv_color_hex(0x1A1A1A)
#define COLOR_CARD_BG2      lv_color_hex(0x222222)
#define COLOR_TEXT_PRIMARY   lv_color_hex(0xFFFFFF)
#define COLOR_TEXT_SECONDARY lv_color_hex(0xAAAAAA)
#define COLOR_TEXT_DIM       lv_color_hex(0x666666)
#define COLOR_RED            lv_color_hex(0xFF3B30)
#define COLOR_RED_DARK       lv_color_hex(0xCC2F26)
#define COLOR_GREEN          lv_color_hex(0x34C759)
#define COLOR_BLUE           lv_color_hex(0x007AFF)
#define COLOR_BLUE_DARK      lv_color_hex(0x0055CC)
#define COLOR_YELLOW         lv_color_hex(0xFFCC00)
#define COLOR_ORANGE         lv_color_hex(0xFF9500)
#define COLOR_PROGRESS_BG    lv_color_hex(0x333333)
#define COLOR_BORDER         lv_color_hex(0x333333)

/* Vital sign normal ranges */

#define HR_LOW              55
#define HR_HIGH             100
#define SPO2_LOW            95
#define TEMP_LOW            35.5f
#define TEMP_HIGH           37.3f
#define DAILY_STEPS_GOAL    6000

/* SOS countdown seconds */

#define SOS_COUNTDOWN_SEC   10

/* API server URL */

#define SERVER_URL          CONFIG_EXAMPLES_ELDERLY_BES_SERVER_URL
#define DEVICE_SN           CONFIG_EXAMPLES_ELDERLY_BES_DEVICE_SN
#define DEFAULT_INTERVAL    CONFIG_EXAMPLES_ELDERLY_BES_DEFAULT_INTERVAL

/****************************************************************************
 * Public Type Definitions
 ****************************************************************************/

/* Page identifiers */

typedef enum
{
  PAGE_INDEX = 0,
  PAGE_HEALTH_DETAIL,
  PAGE_SETTINGS,
  PAGE_WIFI,
  PAGE_SOS,
  PAGE_COUNT
} page_id_t;

/* Vital sign data */

typedef struct
{
  int32_t  heart_rate;       /* bpm */
  int32_t  spo2;             /* percentage */
  float    temperature;      /* celsius */
  int32_t  steps;            /* daily step count */
  int32_t  battery;          /* battery percentage */
  bool     device_online;    /* device connection status */
  uint64_t timestamp;        /* last update timestamp (ms) */
} vital_data_t;

/* Heart rate history entry */

typedef struct
{
  char     time_str[8];      /* "HH:MM" */
  int32_t  value;            /* bpm */
} hr_history_entry_t;

/* Application settings */

typedef struct
{
  int32_t  brightness;       /* 0-100 */
  int32_t  collect_interval; /* seconds */
  bool     sos_enabled;      /* SOS alarm enabled */
  bool     fall_detect;      /* Fall detection enabled */
  bool     use_sim_data;     /* Use simulated sensor data */
  bool     use_mqtt;         /* true=MQTT, false=HTTP */
} app_settings_t;

/* Alarm state */

typedef struct
{
  bool     active;           /* Alarm is currently triggered */
  int32_t  countdown;        /* Remaining seconds */
  char     alarm_type[16];   /* "SOS", "FALL", "VITAL_ABNORMAL" */
  char     location[128];    /* Location text */
  vital_data_t snapshot;     /* Vital signs at alarm time */
} alarm_state_t;

/* Application global context */

typedef struct
{
  vital_data_t      vitals;
  app_settings_t    settings;
  alarm_state_t     alarm;
  hr_history_entry_t hr_history[24];
  int32_t           hr_history_count;
  page_id_t         current_page;
  bool              network_connected;
  char              server_url[128];
  char              device_sn[32];
  char              access_token[512];
} app_context_t;

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Global context accessor */

app_context_t *app_get_context(void);

/* Vital sign status helpers */

const char *get_hr_status(int32_t hr);
lv_color_t get_hr_status_color(int32_t hr);
const char *get_spo2_status(int32_t spo2);
lv_color_t get_spo2_status_color(int32_t spo2);
const char *get_temp_status(float temp);
lv_color_t get_temp_status_color(float temp);

/* UI style helpers */

void apply_card_style(lv_obj_t *obj);
void apply_rounded_btn_style(lv_obj_t *obj, lv_color_t bg_color);
void create_dot_indicator(lv_obj_t *parent, lv_color_t color,
                          lv_coord_t x, lv_coord_t y);

#endif /* __UI_COMMON_H */

