1	/****************************************************************************
2	 * apps/examples/elderly/ui_manager.c
3	 *
4	 * Page manager: handles page creation, switching, and lifecycle.
5	 ****************************************************************************/
6	
7	/****************************************************************************
8	 * Included Files
9	 ****************************************************************************/
10	
11	#include "ui_manager.h"
12	#include "ui_index.h"
13	#include "ui_health_detail.h"
14	#include "ui_settings.h"
15	#include "ui_wifi.h"
16	#include "ui_sos.h"
17	
18	/****************************************************************************
19	 * Private Data
20	 ****************************************************************************/
21	
22	static lv_obj_t *g_pages[PAGE_COUNT];
23	static lv_obj_t *g_layer;     /* Top-level layer for overlays */
24	static page_id_t g_current = PAGE_INDEX;
25	
26	/****************************************************************************
27	 * Private Functions
28	 ****************************************************************************/
29	
30	static void swipe_event_cb(lv_event_t *e)
31	{
32	  lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
33	  app_context_t *ctx = app_get_context();
34	
35	  /* Don't allow swipe navigation when SOS is active */
36	
37	  if (ctx->alarm.active)
38	    {
39	      return;
40	    }
41	
42	  if (dir == LV_DIR_LEFT)
43	    {
44	      if (g_current < PAGE_COUNT - 1)
45	        {
46	          ui_manager_switch_page(g_current + 1);
47	        }
48	    }
49	  else if (dir == LV_DIR_RIGHT)
50	    {
51	      if (g_current > PAGE_INDEX)
52	        {
53	          ui_manager_switch_page(g_current - 1);
54	        }
55	    }
56	}
57	
58	/****************************************************************************
59	 * Public Functions
60	 ****************************************************************************/
61	
62	void ui_manager_init(void)
63	{
64	  lv_obj_t *scr = lv_screen_active();
65	
66	  /* Set black background */
67	
68	  lv_obj_set_style_bg_color(scr, COLOR_BG, 0);
69	  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
70	  lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
71	
72	  /* Create the content layer */
73	
74	  g_layer = lv_obj_create(scr);
75	  lv_obj_set_size(g_layer, SCREEN_WIDTH, SCREEN_HEIGHT);
76	  lv_obj_center(g_layer);
77	  lv_obj_set_style_bg_opa(g_layer, LV_OPA_TRANSP, 0);
78	  lv_obj_set_style_border_width(g_layer, 0, 0);
79	  lv_obj_set_style_pad_all(g_layer, 0, 0);
80	  lv_obj_remove_flag(g_layer, LV_OBJ_FLAG_SCROLLABLE);
81	
82	  /* Create all pages */
83	
84	  g_pages[PAGE_INDEX] = ui_index_create(g_layer);
85	  g_pages[PAGE_HEALTH_DETAIL] = ui_health_detail_create(g_layer);
86	  g_pages[PAGE_SETTINGS] = ui_settings_create(g_layer);
87	  g_pages[PAGE_WIFI] = ui_wifi_create(g_layer);
88	  g_pages[PAGE_SOS] = ui_sos_create(g_layer);
89	
90	  /* Hide all except the first page */
91	
92	  for (int i = 0; i < PAGE_COUNT; i++)
93	    {
94	      if (i != PAGE_INDEX)
95	        {
96	          lv_obj_add_flag(g_pages[i], LV_OBJ_FLAG_HIDDEN);
97	        }
98	    }
99	
100	  g_current = PAGE_INDEX;
101	
102	  /* Add swipe gesture handler on the active screen */
103	
104	  lv_obj_add_event_cb(scr, swipe_event_cb, LV_EVENT_GESTURE, NULL);
105	}
106	
107	void ui_manager_switch_page(page_id_t page)
108	{
109	  if (page >= PAGE_COUNT || page == g_current)
110	    {
111	      return;
112	    }
113	
114	  /* Hide current page */
115	
