348	void ui_index_update_vitals(void)
349	{
350	  app_context_t *ctx = app_get_context();
351	  char buf[32];
352	
353	  /* Heart rate */
354	
355	  snprintf(buf, sizeof(buf), "%ld", (long)ctx->vitals.heart_rate);
356	  lv_label_set_text(g_hr_label, buf);
357	  lv_obj_set_style_text_color(g_hr_label,
